'use strict';
const makeTheme=(id,name,accent,bg,panel,extra={})=>({id,name,mode:'dark',format:'amago-theme-v1',author:'Âmago',colors:{bg,sidebar:bg,panel,raised:panel,hover:panel,border:'#2b3c53',text:'#bdcbdc',strong:'#ecf3ff',muted:'#8295ae',subtle:'#657992',accent,'accent-bg':panel,purple:'#b3a1ff',...extra}});
const nativeThemes=[makeTheme('orbital','Âmago · Núcleo','#b9a3e3','#0b0c0f','#131419',{sidebar:'#0e0f13',raised:'#1c1c23',hover:'#25242d',border:'#303039',text:'#c6c3ce',strong:'#eeecf3',muted:'#a49dad',subtle:'#938b9e','accent-bg':'#282332',purple:'#b0bfc1'}),makeTheme('cyberpunk','Cyberpunk','#f5ed42','#100f1c','#241b35',{border:'#654168',text:'#e0d8e9',strong:'#faf6b6',muted:'#b29bc4',subtle:'#857499',purple:'#ff4d99'}),makeTheme('midnight','Meia-noite','#aab9ff','#10111b','#1b2032'),makeTheme('forest','Floresta','#90d8a0','#101a16','#1c2d24',{border:'#345142',text:'#bfd5c6',strong:'#e3f4e9',muted:'#8ba896',purple:'#d7bd84'}),makeTheme('rose','Quartzo','#f0aecb','#20141e','#352233',{border:'#5d3b54',text:'#dbc4d5',strong:'#f9e7f3',muted:'#b295a9',purple:'#bea8f0'}),{...makeTheme('daylight','Alvorada','#247b85','#f0f5fb','#e0eaf6',{border:'#c6d5e7',text:'#435770',strong:'#172e4c',muted:'#58708f',subtle:'#7288a4',purple:'#7564ac'}),mode:'light'}];
function themeCatalog(){return nativeThemes}
function applyTheme(){const selected=themeCatalog().find(t=>t.id===vault.skin)||(vault.theme==='light'?nativeThemes.at(-1):nativeThemes[0]);document.body.dataset.skin=selected.id;document.body.classList.toggle('theme-light',selected.mode==='light');vault.theme=selected.mode;for(const [key,value] of Object.entries(selected.colors))document.body.style.setProperty('--'+key,value);document.body.style.setProperty('--glass-rgb',selected.mode==='light'?'231,239,250':selected.id==='cyberpunk'?'20,13,29':selected.id==='forest'?'13,27,21':selected.id==='rose'?'29,14,25':selected.id==='orbital'?'11,12,15':'9,15,27')}
const themedRender=render;
render=function(){themedRender();applyTheme()};
actions.themes=()=>{modal('Aparência e temas','<p>Escolha uma das paletas incluídas no Âmago Free.</p><div class="theme-grid">'+themeCatalog().map(t=>`<button class="theme-tile" data-theme-id="${esc(t.id)}" style="--tile-bg:${t.colors.bg};--tile-panel:${t.colors.panel};--tile-accent:${t.colors.accent}"><span class="theme-preview"><i></i><i></i><i></i></span><strong>${esc(t.name)}</strong></button>`).join('')+'</div>');document.querySelectorAll('[data-theme-id]').forEach(b=>b.onclick=()=>{vault.skin=b.dataset.themeId;applyTheme();persist();render();actions.themes();window.amagoDesktop?.appearance?.({enabled:vault.appearance?.acrylic!==false,theme:vault.theme})})};
